// not cover that type. Matched by type alone, so with two swords insured both
// sword damages resolve to the first. That is harmless while every item of a
// type is interchangeable for reimbursement purposes; the case that forces a
// positional match is rejecting more damage entries of a type than the policy
// covers, which needs a count rather than a lookup.
const insuredItemFor = (
  policy: IssuedPolicy,
  damage: Damage,
): Item | undefined =>
  policy.items.find((item) => item.type === damage.itemType);

// Grounds on which a claim is refused outright, checked over the whole incident
// before any money is computed. Stated here, once and up front, for the same
// reason `rejectUninsurableItems` is: a rejection is a rule in its own right,
// not something that should fall out of whichever pricing step happens to trip
// over it first.
//
// Keeping them here also keeps `reimbursableForDamage` total — it is called
// from a summation, and a function that can throw partway through an
// accumulation is doing control flow through the accumulator.
//
// This is the incident-level pass, so a rule that needs to see all the damages
// at once — counting entries per type against what the policy covers — has a
// home here, whereas it could never live inside a per-damage function.
const rejectUnclaimableIncident = (
  policy: IssuedPolicy,
  incident: Incident,
): void => {
  for (const damage of incident.damages) {
    // Damage is a loss, never a credit.
    if (damage.amount < 0) {
      throw new Error(`negative damage amount: ${damage.amount}`);
    }

    // A policy only answers for what it covers.
    if (insuredItemFor(policy, damage) === undefined) {
      throw new Error(`item not covered by the policy: ${damage.itemType}`);
    }
  }
};

